css='''*{box-sizing:border-box}body{margin:0;background:#073c30;color:#f4efe2;font:17px/1.8 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:#a4ed91;text-underline-offset:5px}header,main,footer{max-width:1020px;margin:auto;padding:32px}header{display:flex;justify-content:space-between;border-bottom:1px solid #ffffff25}nav{display:flex;gap:24px;flex-wrap:wrap}.hero{padding:65px 0 48px;display:grid;grid-template-columns:1fr 220px;gap:40px;align-items:center}.hero img{width:220px;border-radius:44px}h1{font-family:Georgia,serif;font-size:clamp(38px,7vw,72px);font-weight:400;line-height:1.12;margin:22px 0}h2{font-weight:500;font-size:25px;margin-top:42px}.eyebrow{font-size:12px;letter-spacing:3px;color:#a4ed91}.lead{font-size:21px;color:#bdd6c8;max-width:650px}.badge{display:inline-block;padding:7px 14px;border:1px solid #a4ed9660;border-radius:30px;font-size:14px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;margin:40px 0}.steps article{border-top:1px solid #ffffff35}.steps h2{margin-top:20px}.number{font-family:Georgia,serif;color:#ebc276;font-size:30px}.text{max-width:720px}.text p{color:#d3dfd6}footer{border-top:1px solid #ffffff25;color:#bdd6c8;font-size:14px}button{font:inherit}details{border-top:1px solid #ffffff25;padding:20px 0}summary{cursor:pointer;font-weight:600}.en{color:#b8d1c3;font-size:.95em}@media(max-width:650px){header,main,footer{padding:24px}.hero{padding:30px 0;grid-template-columns:1fr}.hero img{width:120px;border-radius:26px;grid-row:1}.steps{grid-template-columns:1fr;gap:15px}nav{gap:15px}.lead{font-size:18px}}'''
